package country

// Flags are shown in the "rectangle" (1.51:1) image frame of the buttons
// template.
const (
	frameW = 151
	frameH = 100

	// maxCropPercent is how much of a flag's width or height may be cut off
	// to fill the frame. Flags that would lose more are shown whole.
	maxCropPercent = 10
)

// flagInfo describes a flag image. flagInfos in flags_gen.go is generated by
// tools/fetchflags.
type flagInfo struct {
	W, H   int
	Corner uint32 // 0xRRGGBB at the top corners when shown in the frame
}

// FlagFitsFrame reports whether the flag can fill the image frame of the
// buttons template ("cover") without losing more than maxCropPercent of its
// width or height. It is false for a code without a known flag size, so the
// flag is shown whole ("contain").
func (c *Country) FlagFitsFrame() bool {
	s := flagInfos[c.Code]
	return fitsFrame(s.W, s.H)
}

// FlagCornerColor returns the colour of the flag's top corners as shown in
// the image frame, "#RRGGBB". When the left and right corners differ it is
// the mean of the two. It is "" for a code without a known flag.
func (c *Country) FlagCornerColor() string {
	f, ok := flagInfos[c.Code]
	if !ok {
		return ""
	}
	return hexColor(f.Corner)
}

// hexColor formats 0xRRGGBB as "#RRGGBB" without fmt.
func hexColor(rgb uint32) string {
	const digits = "0123456789ABCDEF"
	b := [7]byte{'#'}
	for i := 6; i > 0; i-- {
		b[i] = digits[rgb&0xF]
		rgb >>= 4
	}
	return string(b[:])
}

// FrameCrop returns how many pixels a w x h image loses on each side
// (left and right, or top and bottom) when it fills the frame ("cover")
// centred. Exactly one of dx, dy is non-zero unless the image has the
// frame's shape. Invalid sizes return 0, 0.
func FrameCrop(w, h int) (dx, dy int) {
	if w <= 0 || h <= 0 {
		return 0, 0
	}
	if w*frameH >= h*frameW {
		shownW := h * frameW / frameH
		return (w - shownW) / 2, 0
	}
	shownH := w * frameH / frameW
	return 0, (h - shownH) / 2
}

// fitsFrame reports whether a w x h image fills the frame ("cover") losing at
// most maxCropPercent of its width or height. Invalid sizes report false so
// the image is shown whole.
func fitsFrame(w, h int) bool {
	if w <= 0 || h <= 0 {
		return false
	}
	keep := 100 - maxCropPercent
	if w*frameH >= h*frameW {
		// Wider than the frame: the kept width is (frameW/frameH)*h of w.
		return frameW*h*100 >= keep*frameH*w
	}
	// Narrower than the frame: the kept height is (frameH/frameW)*w of h.
	return frameH*w*100 >= keep*frameW*h
}
